import {addRooftop} from './rooftops.js';
import * as T from 'three';
// Visual reconstruction from the supplied Fujin Street reference; dimensions are illustrative.
export function createFujinStreet(world,facade){
const scene=new T.Group();world.add(scene);
const mats={};const mat=c=>mats[c]??=new T.MeshStandardMaterial({color:c,roughness:.88});
function box(w,h,d,x,y,z,c,parent=scene){const o=new T.Mesh(new T.BoxGeometry(w,h,d),typeof c==='string'?mat(c):c);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
const tile=document.createElement('canvas');tile.width=tile.height=256;const ctx=tile.getContext('2d');ctx.fillStyle='#b9b7a9';ctx.fillRect(0,0,256,256);ctx.strokeStyle='#98998e';ctx.lineWidth=2;for(let k=0;k<=256;k+=16){ctx.beginPath();ctx.moveTo(k,0);ctx.lineTo(k,256);ctx.stroke();ctx.beginPath();ctx.moveTo(0,k);ctx.lineTo(256,k);ctx.stroke()}const tileMap=new T.CanvasTexture(tile);tileMap.wrapS=tileMap.wrapT=T.RepeatWrapping;tileMap.repeat.set(2,1);tileMap.colorSpace=T.SRGBColorSpace;const tileMat=new T.MeshStandardMaterial({map:tileMap,roughness:.95});
facade.traverse(o=>{if(o.isMesh&&o.material.color){const c=o.material.color.getHexString();if(['c3c2b4','b4b9ad','a7b0ab'].includes(c))o.material=tileMat}});
function details(x,base,z,side,parent,floors=5){for(let f=1;f<floors;f++){const y=base+f*3.2;box(11,.32,.09,x,y+.65,z, '#875e51',parent);for(let k=0;k<4;k++){const wx=x-4+k*2.65;if((f+k)%3!==0){for(let n=0;n<7;n++)box(.027,1.8,.045,wx-.85+n*.28,y+1.9,z+side*.48,'#8e9990',parent);box(1.85,.035,.05,wx,y+1.35,z+side*.48,'#9fa79b',parent);box(1.85,.035,.05,wx,y+2.4,z+side*.48,'#9fa79b',parent)}if((f+k)%2===0){const awning=box(2,.06,.9,wx,y+2.85,z+side*.55,'#78958a',parent);awning.rotation.x=side*.15}}}}
details(0,0,4.25,1,facade);
// Open double-leaf entrance with a visible passage instead of an opaque backing panel.
function entrance(parent,x,z,main=false){const steel=new T.MeshStandardMaterial({color:'#a6b7b3',metalness:.7,roughness:.28});const glass=new T.MeshPhysicalMaterial({color:'#8ca7a2',transparent:true,opacity:.16,roughness:.1,metalness:.08,depthWrite:false});
box(2.05,.07,4.1,x,.345,z-1.8,'#8f968b',parent);for(const side of [-1,1]){box(.16,2.68,main?.65:3.8,x+side*1.02,1.65,main?z-.325:z-1.8,'#c0c2b2',parent);box(.07,2.6,.1,x+side*.92,1.66,z,steel,parent);const leaf=new T.Group();leaf.position.set(x+side*.88,.38,z);leaf.rotation.y=side<0?-Math.PI*.51:Math.PI*.51;parent.add(leaf);const cx=-side*.43;box(.81,2.36,.022,cx,1.23,0,glass,leaf);for(const y of [.03,.7,2.47])box(.86,.045,.065,cx,y,0,steel,leaf);for(const dx of [0,-side*.85])box(.045,2.5,.065,dx,1.25,0,steel,leaf);box(.035,.4,.1,-side*.7,1.16,.06,steel,leaf)}
box(2.18,.2,.4,x,3,z,'#b9bbaa',parent);box(1.85,.05,.1,x,2.95,z,steel,parent);box(2.25,.12,1,x,3.15,z+.25,'#72897f',parent);box(.22,.35,.07,x+1.17,1.53,z+.12,steel,parent);box(.12,.08,.08,x+1.17,1.6,z+.15,'#263731',parent);
for(let n=0;n<8;n++)box(1.7,.022,.018,x,.39,z-.25-n*.44,'#c0c4b6',parent);
box(.045,.7,.6,x+.91,1.16,z-.34,'#64736e',parent);for(let n=0;n<6;n++){box(.05,.18,.21,x+.87,.95+Math.floor(n/2)*.21,z-.22-(n%2)*.23,steel,parent);box(.057,.018,.15,x+.86,1+Math.floor(n/2)*.21,z-.22-(n%2)*.23,'#263731',parent);}
const luminous=new T.MeshStandardMaterial({color:'#fff3d6',emissive:'#ffe6ba',emissiveIntensity:2});box(.55,.06,.16,x,2.81,z-1,luminous,parent);if(main){const light=new T.PointLight('#ffedcc',9,7,2);light.position.set(x,2.5,z-1);parent.add(light);box(2,.1,2.8,x,2.96,z-1.4,'#c2c4b7',parent)}
}
entrance(facade,0,4.08,true);
function apartment(x,z,opposite,index){const g=new T.Group();g.position.set(x,0,z);if(opposite)g.rotation.y=Math.PI;scene.add(g);const h=12.8+(index%2)*3.2;box(11.7,h-3,7.5,0,3+(h-3)/2,0,tileMat,g);box(4.7,3,7.5,-3.5,1.5,0,tileMat,g);box(4.7,3,7.5,3.5,1.5,0,tileMat,g);box(2.3,3,.2,0,1.5,-3.7,tileMat,g);box(11.9,.2,7.8,0,h+.08,0,'#a8aa9d',g);for(let f=0;f<h/3.2;f++){for(let k=0;k<4;k++){if(f===0&&(k===1||k===2))continue;const wx=-4+k*2.65;box(2.1,1.8,.06,wx,f*3.2+1.85,3.79,'#536362',g);box(.055,1.82,.06,wx,f*3.2+1.85,3.84,'#c1c5b7',g);box(2.1,.055,.06,wx,f*3.2+1.85,3.84,'#b9bcae',g);if(f>0){box(2.35,.16,.85,wx,f*3.2+.82,4.06,'#abad9d',g);if((k+f)%2===0)box(.65,.4,.4,wx+.5,f*3.2+2.56,4.05,'#c1c5bd',g)}}if(f>0)box(11.7,.35,.08,0,f*3.2+.65,3.82,index%2?'#946c5c':'#8e8070',g)}details(0,0,3.86,1,g,h/3.2);box(11.6,.48,.18,0,2.9,3.9,'#b8b9a5',g);for(let k=0;k<2;k++){box(3.3,2.4,.08,-3.7+k*7.4,1.25,3.92,'#53635e',g);for(let n=0;n<12;n++)box(3.2,.025,.04,-3.7+k*7.4,.3+n*.16,3.98,'#7d877e',g)}entrance(g,0,3.99);addRooftop(g,h+.18,Math.round(Math.abs(x)/12.6)+(opposite?2:0));return g}
for(const x of [-38,-25.3,-12.6,12.6,25.3,38])apartment(x,0,false,Math.abs(Math.round(x))%3);for(const x of [-38,-25.3,-12.6,0,12.6,25.3,38])apartment(x,25,true,Math.abs(Math.round(x))%3);
box(90,.25,6,0,.05,20.5,'#8b8f83');box(90,.18,.22,0,.06,6,'#b3b6aa');box(90,.18,.22,0,.06,17.5,'#b3b6aa');
// Paired yellow center lines and parking bay outlines.

for(const z of [11.8,12.05])box(32,.014,.07,-29,-.048,z,'#d6bd62');for(let x=-11;x<44;x+=5)box(2.6,.014,.09,x,-.048,11.9,'#d6bd62');
for(const side of [0,1])for(let x=-40;x<=40;x+=8){const near=side?14.7:6.7,far=side?17.2:9.7;for(const z of [near,far])box(5.7,.014,.065,x,-.044,z,'#ddded1');for(const dx of [-2.85,2.85])box(.065,.014,far-near,x+dx,-.044,(near+far)/2,'#ddded1')}
// White straight-ahead arrows, oriented with each lane.
for(const [x,z,sign] of [[-17,10.5,-1],[17,13.35,1]]){box(1.7,.016,.11,x,-.04,z,'#dedfd1');for(const side of [-1,1]){const b=box(.7,.016,.11,x+sign*.8,-.04,z+side*.22,'#dedfd1');b.rotation.y=side*sign*.65}}
const trunkMat=mat('#74735d'),leafMats=['#425b38','#526c40','#627a48','#3e5737'].map(mat);const foliageGeo=new T.IcosahedronGeometry(1,1);let seed=53;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}
function tree(x,z,index){box(1.3,.08,1.3,x,.19,z,'#626955');const trunk=new T.Mesh(new T.CylinderGeometry(.15,.26,4.6,9),trunkMat);trunk.position.set(x,2.47,z);trunk.castShadow=true;scene.add(trunk);for(let k=0;k<3;k++){const branch=new T.Mesh(new T.CylinderGeometry(.07,.12,2.8,7),trunkMat);branch.position.set(x+Math.sin(k*2.1)*.5,4.2,z+Math.cos(k*2.1)*.5);branch.rotation.z=Math.sin(k*2.1)*.5;branch.rotation.x=Math.cos(k*2.1)*.5;scene.add(branch)}for(let k=0;k<4;k++){const count=28,leaves=new T.InstancedMesh(foliageGeo,leafMats[k],count);const d=new T.Object3D();for(let n=0;n<count;n++){const a=rand()*Math.PI*2,r=Math.sqrt(rand())*2.3;d.position.set(x+Math.cos(a)*r,5.3+rand()*2.3,z+Math.sin(a)*r);d.scale.set(.45+rand()*.6,.55+rand()*.5,.5+rand()*.7);d.rotation.set(rand(),rand(),rand());d.updateMatrix();leaves.setMatrixAt(n,d.matrix)}leaves.castShadow=true;leaves.receiveShadow=true;scene.add(leaves)}}
for(const x of [-40,-29,-18,-7,7,19,30,41])tree(x,5.3,0);for(const x of [-39,-28,-17,-6,6,18,29,40])tree(x,18.2,1);
// Non-emergency parked vehicles cleared from the training scene.
// Combine fixed street geometry by material to reduce draw calls on phones.
scene.updateMatrixWorld(true);const batches=new Map(),originals=[];scene.traverse(o=>{if(!o.isMesh||o.isInstancedMesh)return;const g=o.geometry.index?o.geometry.toNonIndexed():o.geometry.clone();g.applyMatrix4(o.matrixWorld);if(!batches.has(o.material))batches.set(o.material,[]);batches.get(o.material).push(g);originals.push(o)});for(const o of originals)o.parent.remove(o);for(const [material,geometries] of batches){const merged=new T.BufferGeometry();for(const name of ['position','normal','uv']){const size=name==='uv'?2:3;const total=geometries.reduce((n,g)=>n+g.attributes.position.count*size,0);const data=new Float32Array(total);let cursor=0;for(const g of geometries){const a=g.attributes[name];if(a)data.set(a.array,cursor);cursor+=g.attributes.position.count*size}merged.setAttribute(name,new T.BufferAttribute(data,size))}const mesh=new T.Mesh(merged,material);mesh.userData.collisionBoxes=geometries.map(g=>{g.computeBoundingBox();return g.boundingBox.clone()});mesh.castShadow=true;mesh.receiveShadow=true;scene.add(mesh);geometries.forEach(g=>g.dispose())}originals.forEach(o=>o.geometry.dispose());
return {tileMat};
}
